const memoryStorage=new Map();
function storeGet(key,fallback=null){try{const v=window.localStorage.getItem(key);return v===null?fallback:v;}catch{return memoryStorage.has(key)?memoryStorage.get(key):fallback;}}
function storeSet(key,value){value=String(value);memoryStorage.set(key,value);try{window.localStorage.setItem(key,value);return true;}catch{return false;}}
