function colName(n){let s='';while(n>0){const r=(n-1)%26;s=String.fromCharCode(65+r)+s;n=Math.floor((n-1)/26);}return s;}
function colNum(s){return s.replace(/\$/g,'').toUpperCase().split('').reduce((n,ch)=>n*26+ch.charCodeAt(0)-64,0);}
function address(r,c){return colName(c)+r;}
function parseAddress(s){const m=String(s||'').toUpperCase().match(/^\$?([A-Z]{1,3})\$?(\d+)$/);return m?{r:+m[2],c:colNum(m[1])}:null;}
function mkSheet(name='Sheet1'){return{id:`s${Date.now().toString(36)}${Math.random().toString(36).slice(2,6)}`,name,cells:{},colWidths:{},rowHeights:{},merges:[],validation:{},conditionalRules:[],filter:null,freezeRows:0,showGridlines:true};}
function createBook(name='My Spreadsheet'){return{name,sheets:[mkSheet()],activeSheet:0,createdAt:Date.now(),updatedAt:Date.now()};}
function sheet(){return wb.sheets[wb.activeSheet]||wb.sheets[0];}
function clone(o){return JSON.parse(JSON.stringify(o));}
function cell(sh,a,create=false){a=String(a).toUpperCase();if(!sh.cells[a]&&create)sh.cells[a]={v:''};return sh.cells[a]||{v:''};}
function raw(sh,a){return cell(sh,a).v??'';}
function setCell(sh,a,v,style){a=String(a).toUpperCase();if(v===''||v===null||v===undefined){if(sh.cells[a]?.s&&Object.keys(sh.cells[a].s).length)sh.cells[a].v='';else delete sh.cells[a];}else{const o=sh.cells[a]||{v:''};o.v=String(v);if(style)o.s={...(o.s||{}),...style};sh.cells[a]=o;}cache.clear();}
function setRows(sh,rows){rows.forEach((row,ri)=>row.forEach((v,ci)=>{if(v!==''&&v!==null&&v!==undefined)setCell(sh,address(ri+1,ci+1),v);}));}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function xmlEsc(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');}
function getUsed(sh){let r=10,c=8;for(const a of Object.keys(sh.cells)){const p=parseAddress(a);if(p){r=Math.max(r,p.r);c=Math.max(c,p.c);}}return{r:Math.min(MAX_R,Math.max(50,r+10)),c:Math.min(MAX_C,Math.max(16,c+4))};}
function literal(v){const s=String(v??'').trim();if(!s)return'';if(s.toUpperCase()==='TRUE')return true;if(s.toUpperCase()==='FALSE')return false;if(/^-?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?$/i.test(s))return Number(s);return String(v);}
function num(v){if(v===true)return 1;if(v===false)return 0;if(v===''||v===null||v===undefined)return 0;if(typeof v==='number')return v;const n=Number(v);return Number.isNaN(n)?NaN:n;}
function isError(v){return typeof v==='string'&&/^#(REF!|DIV\/0!|VALUE!|NAME\?|NUM!|CYCLE!|N\/A|ERROR!)/.test(v);}
function computed(sh,a,stack=[]){a=String(a).toUpperCase();if(stack.includes(a))return '#CYCLE!';const k=sh.id+':'+a;if(!stack.length&&cache.has(k))return cache.get(k);const v=raw(sh,a);if(v==='')return'';let out;if(String(v).startsWith('=')){try{out=evalFormula(String(v).slice(1),sh,[...stack,a]);}catch(e){out=e?.sheetError||'#VALUE!';}}else out=literal(v);if(typeof out==='number'&&!Number.isFinite(out))out='#NUM!';if(!stack.length)cache.set(k,out);return out;}
function tokens(s){const out=[];for(let i=0;i<s.length;){if(/\s/.test(s[i])){i++;continue;}const rest=s.slice(i);if(s[i]==='"'){let j=i+1,v='';while(j<s.length){if(s[j]==='"'&&s[j+1]==='"'){v+='"';j+=2;continue;}if(s[j]==='"')break;v+=s[j++];}if(j>=s.length)throw{sheetError:'#VALUE!'};out.push({t:'str',v});i=j+1;continue;}let m=rest.match(/^(?:\d+\.\d*|\.\d+|\d+)(?:[Ee][+-]?\d+)?/);if(m){out.push({t:'num',v:m[0]});i+=m[0].length;continue;}m=rest.match(/^\$?[A-Za-z]{1,3}\$?\d+/);if(m&&!/[A-Za-z0-9_.]/.test(rest[m[0].length]||'')){out.push({t:'ref',v:m[0]});i+=m[0].length;continue;}m=rest.match(/^[A-Za-z_][A-Za-z0-9_.]*/);if(m){out.push({t:'id',v:m[0]});i+=m[0].length;continue;}m=rest.match(/^(?:<=|>=|<>|[+\-*/^&=<>():,;])/);if(m){out.push({t:'op',v:m[0]});i+=m[0].length;continue;}throw{sheetError:'#VALUE!'};}return out;}
function evalFormula(formula,sh,stack){const ts=tokens(formula);let i=0,peek=()=>ts[i],take=()=>ts[i++],match=(...v)=>peek()&&v.includes(peek().v)?(i++,true):false,expect=v=>{if(!match(v))throw{sheetError:'#VALUE!'};};const deref=v=>v&&v.__ref?computed(sh,v.a,stack):v;
 function cmp(){let a=concat();while(peek()&&['=','<>','>','<','>=','<='].includes(peek().v)){const op=take().v,b=concat();a=compare(deref(a),deref(b),op);}return a;}
 function concat(){let a=add();while(match('&'))a=String(deref(a)??'')+String(deref(add())??'');return a;}
 function add(){let a=mul();while(peek()&&['+','-'].includes(peek().v)){const op=take().v,b=mul(),x=num(deref(a)),y=num(deref(b));a=Number.isNaN(x)||Number.isNaN(y)?'#VALUE!':op==='+'?x+y:x-y;}return a;}
 function mul(){let a=unary();while(peek()&&['*','/'].includes(peek().v)){const op=take().v,b=unary(),x=num(deref(a)),y=num(deref(b));a=Number.isNaN(x)||Number.isNaN(y)?'#VALUE!':op==='/'&&y===0?'#DIV/0!':op==='*'?x*y:x/y;}return a;}
 function unary(){if(match('+'))return num(deref(unary()));if(match('-')){const v=num(deref(unary()));return Number.isNaN(v)?'#VALUE!':-v;}return power();}
 function power(){let a=primary();if(match('^')){const b=unary(),x=num(deref(a)),y=num(deref(b));a=Number.isNaN(x)||Number.isNaN(y)?'#VALUE!':Math.pow(x,y);}return a;}
 function primary(){const t=take();if(!t)throw{sheetError:'#VALUE!'};if(t.t==='num')return Number(t.v);if(t.t==='str')return t.v;if(t.v==='('){const v=cmp();expect(')');return v;}if(t.t==='ref'){const p=parseAddress(t.v);if(!p)return'#REF!';if(match(':')){const end=take();if(!end||end.t!=='ref')return'#REF!';const q=parseAddress(end.v);if(!q)return'#REF!';const vals=[],refs=[];for(let r=Math.min(p.r,q.r);r<=Math.max(p.r,q.r);r++)for(let c=Math.min(p.c,q.c);c<=Math.max(p.c,q.c);c++){const a=address(r,c);refs.push(a);vals.push(computed(sh,a,stack));}return{__range:true,values:vals,refs,rows:Math.abs(q.r-p.r)+1,cols:Math.abs(q.c-p.c)+1};}return computed(sh,address(p.r,p.c),stack);}if(t.t==='id'){const name=t.v.toUpperCase();if(name==='TRUE')return true;if(name==='FALSE')return false;if(!match('('))return'#NAME?';const args=[];if(!match(')')){do{args.push(cmp());}while(match(',', ';'));expect(')');}return func(name,args);}return'#VALUE!';}
 const v=cmp();return i<ts.length?'#VALUE!':v;}
function flatten(args){return args.flatMap(x=>x&&x.__range?x.values:Array.isArray(x)?x:[x]);}
function truth(v){if(isError(v))return false;if(typeof v==='boolean')return v;if(typeof v==='number')return v!==0;return v!==''&&v!==null&&v!==undefined&&String(v).toLowerCase()!=='false';}
function compare(a,b,op){const an=num(a),bn=num(b),numeric=(typeof a==='number'||typeof b==='number')&&Number.isFinite(an)&&Number.isFinite(bn);const x=numeric?an:String(a??'').toLowerCase(),y=numeric?bn:String(b??'').toLowerCase();switch(op){case'=':return x===y;case'<>':return x!==y;case'>':return x>y;case'<':return x<y;case'>=':return x>=y;case'<=':return x<=y;default:return false;}}
function criteria(value,c){const m=String(c??'').match(/^(>=|<=|<>|>|<|=)(.*)$/);return m?compare(value,literal(m[2]),m[1]):String(value??'').toLowerCase()===String(c??'').toLowerCase();}
function func(name,args){const flat=flatten(args),nums=flat.filter(v=>v!==''&&typeof v!=='boolean'&&!Number.isNaN(Number(v))).map(num);const n=v=>num(v);switch(name){
case'SUM':return nums.reduce((a,b)=>a+b,0);case'PRODUCT':return nums.reduce((a,b)=>a*b,1);case'ABS':return Number.isNaN(n(args[0]))?'#VALUE!':Math.abs(n(args[0]));case'AVERAGE':return nums.length?nums.reduce((a,b)=>a+b,0)/nums.length:'#DIV/0!';case'MIN':return nums.length?Math.min(...nums):0;case'MAX':return nums.length?Math.max(...nums):0;case'COUNT':return nums.length;case'COUNTA':return flat.filter(v=>v!==''&&v!==null&&v!==undefined).length;
case'IF':return truth(args[0])?(args.length>1?args[1]:true):(args.length>2?args[2]:false);case'AND':return flat.every(truth);case'OR':return flat.some(truth);case'NOT':return !truth(args[0]);
case'SUMIF':{const r=args[0]?.__range?args[0].values:[args[0]],sum=args[2]?.__range?args[2].values:r;return r.reduce((s,v,i)=>s+(criteria(v,args[1])&&!Number.isNaN(n(sum[i]))?n(sum[i]):0),0);}case'COUNTIF':{const r=args[0]?.__range?args[0].values:[args[0]];return r.filter(v=>criteria(v,args[1])).length;}case'AVERAGEIF':{const r=args[0]?.__range?args[0].values:[args[0]],av=args[2]?.__range?args[2].values:r,m=r.map((v,i)=>({v:av[i],ok:criteria(v,args[1])})).filter(x=>x.ok&&!Number.isNaN(n(x.v)));return m.length?m.reduce((s,x)=>s+n(x.v),0)/m.length:'#DIV/0!';}
case'ROUND':case'ROUNDUP':case'ROUNDDOWN':{const x=n(args[0]),d=Number(args[1]||0),p=10**Math.max(-10,Math.min(10,d));if(Number.isNaN(x))return'#VALUE!';return name==='ROUND'?Math.sign(x)*Math.round(Math.abs(x)*p)/p:name==='ROUNDUP'?Math.sign(x)*Math.ceil(Math.abs(x)*p)/p:Math.sign(x)*Math.floor(Math.abs(x)*p)/p;}
case'CONCAT':return flat.map(v=>v??'').join('');case'LEFT':return String(args[0]??'').slice(0,Math.max(0,Number(args[1]??1)));case'RIGHT':{const s=String(args[0]??''),k=Math.max(0,Number(args[1]??1));return k?s.slice(-k):'';}case'LEN':return String(args[0]??'').length;case'TRIM':return String(args[0]??'').trim().replace(/\s+/g,' ');
case'VLOOKUP':{const key=args[0],r=args[1],idx=Math.floor(n(args[2]));if(!r?.__range||idx<1||idx>r.cols)return'#VALUE!';for(let rr=0;rr<r.rows;rr++){const row=r.values.slice(rr*r.cols,(rr+1)*r.cols);if(String(row[0]).toLowerCase()===String(key).toLowerCase())return row[idx-1];}return'#N/A';}case'XLOOKUP':{const l=args[1]?.__range?args[1].values:[args[1]],r=args[2]?.__range?args[2].values:[args[2]],i=l.findIndex(v=>String(v).toLowerCase()===String(args[0]).toLowerCase());return i>=0?r[i]:(args.length>3?args[3]:'#N/A');}
case'TODAY':return Math.floor((Date.now()-Date.UTC(1899,11,30))/86400000);case'DAY':case'MONTH':case'YEAR':{const v=args[0],d=typeof v==='number'?new Date(Date.UTC(1899,11,30)+v*86400000):new Date(v);return Number.isNaN(d.getTime())?'#VALUE!':name==='DAY'?d.getUTCDate():name==='MONTH'?d.getUTCMonth()+1:d.getUTCFullYear();}case'MOD':return n(args[1])===0?'#DIV/0!':((n(args[0])%n(args[1]))+n(args[1]))%n(args[1]);case'POWER':return Math.pow(n(args[0]),n(args[1]));default:return'#NAME?';}}
function fmt(sh,a,v){if(v===''||v===null||v===undefined)return'';if(isError(v))return v;const f=cell(sh,a).s?.format;if(typeof v==='number'){if(f==='percent')return `${trim(v*100,2)}%`;if(f==='currency')return `₹${v.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})}`;if(f==='date'){const d=new Date(Date.UTC(1899,11,30)+v*86400000);return d.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'});}if(f==='number')return v.toLocaleString('en-IN',{maximumFractionDigits:2});return trim(v,10);}return String(v);}
function trim(n,k=8){return Number.isFinite(n)?String(Number(n.toFixed(k))):String(n);}
function bound(){return{r1:Math.min(selection.r1,selection.r2),c1:Math.min(selection.c1,selection.c2),r2:Math.max(selection.r1,selection.r2),c2:Math.max(selection.c1,selection.c2)};}
function rangeLabel(b=bound()){return b.r1===b.r2&&b.c1===b.c2?address(b.r1,b.c1):`${address(b.r1,b.c1)}:${address(b.r2,b.c2)}`;}
function pushUndo(){undoStack.push(clone({wb,selection}));if(undoStack.length>60)undoStack.shift();redoStack=[];}
function undo(){if(!undoStack.length){toast('Nothing to undo.');return;}redoStack.push(clone({wb,selection}));const s=undoStack.pop();wb=s.wb;selection=s.selection;cache.clear();saveCurrent();render();toast('Undo complete.');}
function redo(){if(!redoStack.length){toast('Nothing to redo.');return;}undoStack.push(clone({wb,selection}));const s=redoStack.pop();wb=s.wb;selection=s.selection;cache.clear();saveCurrent();render();toast('Redo complete.');}
function savedBooks(){try{const a=JSON.parse(storeGet(STORE.books,'[]'));return Array.isArray(a)?a:[];}catch{return[];}}
function saveCurrent(){wb.updatedAt=Date.now();try{const saved=storeSet(STORE.current,JSON.stringify(wb));$$('#saveIndicator,#editorSaveIndicator').forEach(e=>e.innerHTML=saved?'<i></i> Saved locally':'<i style="background:#d79a36"></i> Session only');}catch{$$('#saveIndicator,#editorSaveIndicator').forEach(e=>e.textContent='Storage full');}}
let saveTimer;function scheduleSave(){$$('#saveIndicator,#editorSaveIndicator').forEach(e=>e.innerHTML='<i style="background:#d79a36"></i> Saving…');clearTimeout(saveTimer);saveTimer=setTimeout(saveCurrent,250);}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400);}
function escapeFile(s){return String(s||'spreadsheet').replace(/[\\/:*?"<>|]+/g,'_').replace(/\s+/g,'_').slice(0,70)||'spreadsheet';}
function download(name,blob){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function saveWorkbook(){const name=$('#workbookName')?.value?.trim();if(name)wb.name=name;wb.id=wb.id||`wb_${Date.now().toString(36)}`;const a=savedBooks(),entry={id:wb.id,name:wb.name,updatedAt:Date.now(),workbook:clone(wb)},i=a.findIndex(x=>x.id===wb.id);if(i>=0)a[i]=entry;else a.unshift(entry);try{const persisted=storeSet(STORE.books,JSON.stringify(a.slice(0,35)));saveCurrent();toast(persisted?'Saved to My Workbooks.':'Saved for this session; browser storage is unavailable. Export an XLSX copy to keep it.');}catch{toast('Storage is full. Export an XLSX copy.');}}
function lessonDone(){try{return JSON.parse(storeGet(STORE.lessons,'{}'));}catch{return{};}}
function challengeDone(){try{return JSON.parse(storeGet(STORE.practice,'{}'));}catch{return{};}}

/* =========================================
   PAGE RENDERING
========================================= */
const pageNames={home:'Home',editor:'Spreadsheet Editor',learn:'Learn Spreadsheets',formulas:'Formula Library',practice:'Practice Lab',projects:'Project Gallery',workbooks:'My Workbooks'};
function setView(){
 view='editor';
 render();
}

function pageIntro(eyebrow,title,desc,actions=''){return `<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="page-intro-actions">${actions}</div></div>`;}
function render(){
 const host=$('#mainContent');
 if(!host)return;
 view='editor';
 cache.clear();
 host.innerHTML=renderEditor();
 renderGrid();
}

function renderHome(){const done=Object.keys(lessonDone()).length,solved=Object.keys(challengeDone()).length;const recent=savedBooks().slice(0,3);return `${pageIntro('YOUR CREATIVE WORKSPACE','Make data make sense.','A friendly spreadsheet studio to organise information, calculate answers, and turn numbers into stories.',`<button class="button button-primary" data-action="new-workbook">＋ New workbook</button>`)}
<div class="welcome-banner"><div class="welcome-copy"><div class="eyebrow">YOUR IDEAS, ORGANIZED</div><h2>Small cells.<br>Big ideas.</h2><p>Build marksheets, budgets, trackers, charts, and useful tools with a real spreadsheet grid. Your work stays in this browser until you export it.</p><div class="welcome-actions"><button class="button" style="background:white;color:var(--primary)" data-action="open-editor">Open spreadsheet editor →</button><button class="button" style="color:white;background:rgba(255,255,255,.15);border-color:rgba(255,255,255,.3)" data-view="projects">Explore projects</button></div></div><div class="welcome-art">📊</div></div>
<div class="stats-grid"><div class="stat-card"><span class="stat-icon purple">📚</span><div><small>Lessons completed</small><strong>${done}/${lessons.length}</strong></div></div><div class="stat-card"><span class="stat-icon blue">🧠</span><div><small>Challenges solved</small><strong>${solved}/${challenges.length}</strong></div></div><div class="stat-card"><span class="stat-icon green">🚀</span><div><small>Starter projects</small><strong>${projects.length}</strong></div></div><div class="stat-card"><span class="stat-icon yellow">📁</span><div><small>Saved workbooks</small><strong>${savedBooks().length}</strong></div></div></div>
<div class="section-heading"><div><h2>Pick up where you want</h2><p>Open the tool that matches your next idea.</p></div></div><div class="quick-grid">
<button class="quick-card" data-view="editor" style="text-align:left"><div class="card-icon green">▦</div><h3>Spreadsheet Editor</h3><p>Enter data, use formulas, format cells, and build charts in an interactive grid.</p><span class="card-link">Open editor →</span></button>
<button class="quick-card" data-view="learn" style="text-align:left"><div class="card-icon blue">📖</div><h3>Learn Spreadsheets</h3><p>Follow short lessons from cell addresses to formulas, data, and charts.</p><span class="card-link">Continue learning →</span></button>
<button class="quick-card" data-view="practice" style="text-align:left"><div class="card-icon pink">🧩</div><h3>Practice Lab</h3><p>Solve realistic tasks by entering formulas into a prepared workbook.</p><span class="card-link">Try a challenge →</span></button>
</div><div class="section-heading"><div><h2>Recently saved</h2><p>Your workbooks are saved on this device.</p></div><button class="text-button" data-view="workbooks">View all</button></div>${recent.length?`<div class="recent-row">${recent.map(x=>`<button class="recent-item" data-action="open-book" data-id="${esc(x.id)}"><span class="recent-icon">📗</span><span><strong>${esc(x.name)}</strong><small>${new Date(x.updatedAt||Date.now()).toLocaleDateString()}</small></span></button>`).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">📁</div><h3>Your saved work will appear here</h3><p>Create a workbook, then choose Save to My Workbooks.</p><button class="button button-primary" data-action="open-editor">Start a spreadsheet</button></div>`}`;}
function renderEditor(){
 return `<div class="editor-page" role="application" aria-label="KidByte Spreadsheet">
   <div class="editor-titlebar">
     <div class="workbook-title">
       <div class="workbook-glyph" aria-hidden="true">▦</div>
       <div class="workbook-title-copy">
         <input id="workbookName" aria-label="Workbook name" value="${esc(wb.name)}">
         <div class="workbook-sub">KidByte Spreadsheet</div>
       </div>
     </div>
     <div class="editor-title-actions">
       <span id="editorSaveIndicator" class="save-indicator"><i></i> Saved locally</span>
       <button class="button button-secondary button-small" data-action="save-book" title="Save workbook">Save</button>
       <button class="button button-secondary button-small" data-action="import-file" title="Open or import a workbook">Open</button>
       <button class="button button-primary button-small" data-action="export-xlsx" title="Download Excel workbook">⇩ XLSX</button>
       <button class="button button-secondary button-small" data-action="export-csv" title="Export active sheet as CSV">CSV</button>
     </div>
   </div>
   <div class="editor-tabs" role="tablist" aria-label="Spreadsheet ribbon">
     ${['File','Home','Insert','Formulas','Data','View'].map(t=>`<button type="button" role="tab" aria-selected="${ribbon===t}" class="editor-tab ${ribbon===t?'active':''}" data-ribbon="${t}">${t}</button>`).join('')}
   </div>
   <div id="toolbarStrip" class="toolbar-strip">${renderToolbar()}</div>
   <div class="name-formula-row">
     <input class="name-box" id="nameBox" value="${rangeLabel()}" aria-label="Cell address or range">
     <span class="fx-mark" aria-hidden="true">fx</span>
     <input class="formula-input" id="formulaInput" value="${esc(raw(sheet(),address(selection.r1,selection.c1)))}" aria-label="Cell value or formula" placeholder="Enter a value or formula">
     <button class="formula-commit" data-action="commit-formula" title="Apply cell value">✓</button>
   </div>
   <div id="chartSlot"></div>
   <div class="grid-shell">
     <div id="sheetViewport" class="sheet-viewport" tabindex="0" aria-label="Worksheet cells">
       <table class="sheet-table" id="sheetTable" aria-label="Spreadsheet grid"></table>
     </div>
   </div>
   <div class="grid-footer">
     <div class="sheet-tabs" id="sheetTabs">${renderSheetTabs()}</div>
     <div class="status-stats" id="statusStats">${statusStats()}</div>
     <div class="zoom-controls">
       <button data-action="zoom-out" title="Zoom out">−</button>
       <span id="zoomValue">${zoom}%</span>
       <button data-action="zoom-in" title="Zoom in">＋</button>
     </div>
   </div>
 </div>`;
}

function renderToolbar(){
 const b=(label,action,title=label)=>`<button type="button" class="tool-button" data-action="${action}" title="${esc(title)}">${label}</button>`;
 const group=html=>`<div class="toolbar-group">${html}</div>`;
 if(ribbon==='File')return group(
   b('＋ New','new-workbook','Create a blank workbook')+
   b('Open / Import','import-file','Open a CSV or XLSX file')+
   b('Open saved','open-saved-books','Open a workbook saved in this browser')+
   b('Save','save-book','Save workbook in this browser')+
   b('Export XLSX','export-xlsx','Download an Excel workbook')+
   b('Export CSV','export-csv','Download the active worksheet as CSV')+
   b('Print','print-sheet','Print active worksheet')
 );
 if(ribbon==='Home')return (
   group(`<select class="tool-select" id="fontFamily" aria-label="Font family"><option>Arial</option><option>Calibri</option><option>Trebuchet MS</option><option>Georgia</option><option>Courier New</option></select><select class="tool-select small-select" id="fontSize" aria-label="Font size"><option>10</option><option>11</option><option selected>12</option><option>14</option><option>16</option><option>18</option><option>22</option></select>`+
   b('<b>B</b>','bold','Bold')+b('<i>I</i>','italic','Italic')+b('<u>U</u>','underline','Underline'))+
   group(`${b('Font colour','font-color')}<input type="color" class="color-pick" id="fontColor" value="#242541" title="Font colour">${b('Cell fill','fill-color')}<input type="color" class="color-pick" id="fillColor" value="#DDEEFF" title="Cell fill colour">`)+
   group(b('Left','align-left','Align left')+b('Centre','align-center','Align centre')+b('Right','align-right','Align right')+b('Wrap','wrap-text','Wrap text')+b('Borders','borders','Apply all borders')+b('Merge','merge-cells','Merge selected cells'))+
   group(`<select class="tool-select" id="numberFormat" aria-label="Number format"><option value="general">General</option><option value="number">Number</option><option value="currency">Currency ₹</option><option value="percent">Percentage</option><option value="date">Date</option></select>`+
   b('Format table','table-style','Apply simple table formatting')+b('Conditional format','conditional-format','Conditional formatting'))+
   group(b('Fill down','fill-down','Fill selected cells down (Ctrl+D)')+b('Fill right','fill-right','Fill selected cells right (Ctrl+R)'))
 );
 if(ribbon==='Insert')return group(
   b('＋ Worksheet','add-sheet')+b('Chart','insert-chart')+b('Table style','table-style')+
   b('Dropdown','dropdown')+b('Date','insert-date')+b('AutoSum ∑','autosum')
 );
 if(ribbon==='Formulas')return group(
   b('AutoSum ∑','autosum')+b('Insert function','formula-picker')+
   b('Function library','go-formulas')+b('Recalculate','recalculate')
 );
 if(ribbon==='Data')return group(
   b('Sort A→Z','sort-asc')+b('Sort Z→A','sort-desc')+b('Filter','toggle-filter')+
   b('Dropdown validation','dropdown')+b('Number validation','number-validation')+
   b('Highlight duplicates','duplicates')+b('Remove duplicates','remove-duplicates')+
   b('Insert row','insert-row')+b('Delete row','delete-row')+
   b('Insert column','insert-column')+b('Delete column','delete-column')+
   b('Freeze top row','freeze-row')+b('Unfreeze','unfreeze')
 );
 return group(
   b(showFormulas?'Show values':'Show formulas','toggle-formulas')+
   b('Gridlines','toggle-grid')+b('Zoom −','zoom-out')+b('Zoom +','zoom-in')+
   b('Find / replace','find-replace')+b('Undo','undo')+b('Redo','redo')+
   b('Print','print-sheet')
 );
}

function renderSheetTabs(){return `${wb.sheets.map((s,i)=>`<button class="sheet-tab ${i===wb.activeSheet?'active':''}" data-action="activate-sheet" data-sheet="${i}" title="Double-click is not required; use Sheet menu">${esc(s.name)}</button>`).join('')}<button class="sheet-add" data-action="add-sheet" title="Add worksheet">＋</button><button class="sheet-add" data-action="sheet-menu" title="Worksheet options">⋯</button>`;}
function statusStats(){const b=bound(),sh=sheet(),vals=[];for(let r=b.r1;r<=b.r2;r++)for(let c=b.c1;c<=b.c2;c++){const v=computed(sh,address(r,c));if(typeof v==='number'&&Number.isFinite(v))vals.push(v);}const sum=vals.reduce((a,v)=>a+v,0),avg=vals.length?sum/vals.length:0;return `<span>Count <strong>${(b.r2-b.r1+1)*(b.c2-b.c1+1)}</strong></span><span>Sum <strong>${trim(sum,2)}</strong></span><span>Average <strong>${trim(avg,2)}</strong></span>`;}
function cellStyle(s={}){let a=[];if(s.bold)a.push('font-weight:900');if(s.italic)a.push('font-style:italic');if(s.underline)a.push('text-decoration:underline');if(s.color)a.push(`color:${s.color}`);if(s.fill)a.push(`background:${s.fill}`);if(s.align)a.push(`text-align:${s.align}`);if(s.fontSize)a.push(`font-size:${s.fontSize}px`);if(s.fontFamily)a.push(`font-family:${JSON.stringify(s.fontFamily)}`);if(s.borders)a.push('box-shadow:inset 0 0 0 1px #aeb3c8');if(s.wrap)a.push('white-space:pre-wrap;overflow-wrap:anywhere');return a.join(';');}
function renderGrid(){const table=$('#sheetTable');if(!table)return;const sh=sheet(),used=getUsed(sh),lastR=Math.min(MAX_R,Math.max(used.r,selection.r1,selection.r2,Math.max(50,...Object.keys(sh.cells).map(a=>parseAddress(a)?.r||1)))),lastC=Math.min(MAX_C,Math.max(used.c,selection.c1,selection.c2,16));const rows=[];rows.push(`<thead><tr><th class="corner">⌘</th>${Array.from({length:lastC},(_,i)=>`<th data-col="${i+1}" style="width:${sh.colWidths?.[i+1]||120}px;min-width:${sh.colWidths?.[i+1]||120}px">${colName(i+1)}<span class="col-resize" data-resize-col="${i+1}"></span></th>`).join('')}</tr></thead><tbody>`);const b=bound();for(let r=1;r<=lastR;r++){if(sh.filter?.active&&r>1&&!rowMatchesFilter(sh,r))continue;rows.push(`<tr class="${sh.freezeRows&&r<=sh.freezeRows?'frozen-row':''}"><th class="row-head" data-row="${r}" style="height:${sh.rowHeights?.[r]||27}px">${r}<span class="row-resize" data-resize-row="${r}"></span></th>`);for(let c=1;c<=lastC;c++){const a=address(r,c),o=cell(sh,a),v=showFormulas&&String(o.v||'').startsWith('=')?o.v:fmt(sh,a,computed(sh,a));const inRange=r>=b.r1&&r<=b.r2&&c>=b.c1&&c<=b.c2;let classes=[];if(inRange)classes.push(r===selection.r1&&c===selection.c1?'selected':'in-range');if(isError(computed(sh,a)))classes.push('error-cell');if(o.s?.wrap)classes.push('wrap-text');if(sh.validation?.[a]?.type==='list')classes.push('validation-cell');const cfRule=(sh.conditionalRules||[]).find(rule=>r>=rule.range.r1&&r<=rule.range.r2&&c>=rule.range.c1&&c<=rule.range.c2&&ruleApplies(rule,computed(sh,a)));if(cfRule)classes.push('cf-cell');const m=(sh.merges||[]).find(x=>x.r1===r&&x.c1===c);const covered=(sh.merges||[]).some(x=>r>=x.r1&&r<=x.r2&&c>=x.c1&&c<=x.c2&&!(x.r1===r&&x.c1===c));if(covered){rows.push(`<td style="display:none" data-cell="${a}"></td>`);continue;}const colspan=m?m.c2-m.c1+1:1,rowspan=m?m.r2-m.r1+1:1;rows.push(`<td data-cell="${a}" data-r="${r}" data-c="${c}" class="${classes.join(' ')}" tabindex="${r===selection.r1&&c===selection.c1?0:-1}" style="${cellStyle(o.s)};${cfRule?`--cf-bg:${cfRule.color};`:''}${m&&colspan>1?`min-width:${colspan*120}px`:''}" ${colspan>1?`colspan="${colspan}"`:''} ${rowspan>1?`rowspan="${rowspan}"`:''}><span class="cell-value">${esc(v)}</span>${r===b.r2&&c===b.c2?'<span class="fill-handle" data-fill-handle="1"></span>':''}</td>`);}rows.push('</tr>');}rows.push('</tbody>');table.innerHTML=rows.join('');table.style.zoom=zoom/100;$('#nameBox').value=rangeLabel();$('#formulaInput').value=raw(sh,address(selection.r1,selection.c1));$('#statusStats').innerHTML=statusStats();$('#sheetTabs').innerHTML=renderSheetTabs();$('#zoomValue').textContent=zoom+'%';renderChartSlot();table.querySelector(`[data-cell="${address(selection.r1,selection.c1)}"]`)?.setAttribute('tabindex','0');}
function ruleApplies(rule,v){if(!rule)return false;const n=num(v),target=num(rule.value);switch(rule.op){case'gt':return Number.isFinite(n)&&n>target;case'lt':return Number.isFinite(n)&&n<target;case'eq':return String(v).toLowerCase()===String(rule.value).toLowerCase();case'blank':return v==='';case'dup':return false;default:return false;}}
function rowMatchesFilter(sh,r){if(!sh.filter||!sh.filter.active)return true;const a=address(r,sh.filter.col);const v=String(computed(sh,a)??'').toLowerCase();return !sh.filter.query||v.includes(sh.filter.query.toLowerCase());}
function updateSelection(r,c,extend=false){r=Math.max(1,Math.min(MAX_R,r));c=Math.max(1,Math.min(MAX_C,c));if(extend){selection.r2=r;selection.c2=c;}else selection={r1:r,c1:c,r2:r,c2:c};if(view==='editor')renderGrid();}
function commitCell(a,v){const sh=sheet();const validation=sh.validation?.[a];if(validation&&validation.type==='number'&&v!==''&&(!Number.isFinite(Number(v))||Number(v)<validation.min||Number(v)>validation.max)){toast(`Enter a number from ${validation.min} to ${validation.max}.`);return false;}if(validation&&validation.type==='list'&&v!==''&&!validation.values.includes(v)){toast(`Choose one of: ${validation.values.join(', ')}`);return false;}pushUndo();setCell(sh,a,v);scheduleSave();renderGrid();return true;}
function editCell(a,initial){const td=$(`[data-cell="${a}"]`);if(!td||td.classList.contains('editing'))return;editing=a;const existing=raw(sheet(),a),input=document.createElement('input');input.className='cell-editor';input.value=initial!==undefined?initial:existing;td.classList.add('editing');td.innerHTML='';td.append(input);input.focus();input.select();const finish=(save,move=0)=>{if(!editing)return;const v=input.value;editing=null;if(save)commitCell(a,v);else renderGrid();if(move){const p=parseAddress(a);updateSelection(p.r+move,p.c);}else{const p=parseAddress(a);selection={r1:p.r,c1:p.c,r2:p.r,c2:p.c};renderGrid();}};input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();finish(true,1);}else if(e.key==='Tab'){e.preventDefault();finish(true,0);const p=parseAddress(a);updateSelection(p.r,p.c+1);}else if(e.key==='Escape'){e.preventDefault();finish(false);}else if(e.key==='ArrowUp'||e.key==='ArrowDown'){if(e.ctrlKey)return;e.preventDefault();finish(true,e.key==='ArrowDown'?1:-1);}});input.addEventListener('blur',()=>{if(editing)finish(true);});}
function fillRangeFromHandle(source,target){
 const b={r1:source.r1,r2:source.r2,c1:source.c1,c2:source.c2};
 const final={r1:Math.min(b.r1,target.r),r2:Math.max(b.r2,target.r),c1:Math.min(b.c1,target.c),c2:Math.max(b.c2,target.c)};
 const extendsSelection=final.r1!==b.r1||final.r2!==b.r2||final.c1!==b.c1||final.c2!==b.c2;
 if(!extendsSelection)return false;
 const sh=sheet(),height=b.r2-b.r1+1,width=b.c2-b.c1+1;
 const mod=(n,m)=>((n%m)+m)%m;
 pushUndo();
 for(let r=final.r1;r<=final.r2;r++){
  for(let c=final.c1;c<=final.c2;c++){
   const isSource=r>=b.r1&&r<=b.r2&&c>=b.c1&&c<=b.c2;
   if(isSource)continue;
   const sr=b.r1+mod(r-b.r1,height),sc=b.c1+mod(c-b.c1,width);
   const srcAddress=address(sr,sc),dstAddress=address(r,c),src=cell(sh,srcAddress);
   const original=raw(sh,srcAddress);
   const translated=translateFormula(original,r-sr,c-sc);
   setCell(sh,dstAddress,translated,src.s?clone(src.s):undefined);
   if(sh.validation?.[srcAddress])sh.validation[dstAddress]=clone(sh.validation[srcAddress]);
  }
 }
 selection={r1:final.r1,c1:final.c1,r2:final.r2,c2:final.c2};
 cache.clear();renderGrid();scheduleSave();
 toast(`Filled ${rangeLabel(final)}.`);
 return true;
}
function fillDown(){
 const b=bound();
 if(b.r1===b.r2){toast('Select the cells to fill, including the destination rows.');return;}
 fillRangeFromHandle({r1:b.r1,c1:b.c1,r2:b.r1,c2:b.c2},{r:b.r2,c:b.c2});
}
function fillRight(){
 const b=bound();
 if(b.c1===b.c2){toast('Select the cells to fill, including the destination columns.');return;}
 fillRangeFromHandle({r1:b.r1,c1:b.c1,r2:b.r2,c2:b.c1},{r:b.r2,c:b.c2});
}

function translateFormula(v,dr,dc){
 const source=String(v??'');
 if(!source.startsWith('='))return source;
 let out='',i=0;
 while(i<source.length){
  if(source[i]==='"'){
   out+=source[i++];
   while(i<source.length){
    out+=source[i];
    if(source[i]==='"'){
     if(source[i+1]==='"'){out+=source[i+1];i+=2;continue;}
     i++;break;
    }
    i++;
   }
   continue;
  }
  const before=source[i-1]||'';
  const match=source.slice(i).match(/^(\$?)([A-Z]{1,3})(\$?)(\d+)/i);
  if(match&&!/[A-Za-z0-9_.]/.test(before)){
   const after=source[i+match[0].length]||'';
   if(!/[A-Za-z0-9_.]/.test(after)){
    const col=colNum(match[2])+(match[1]?0:dc);
    const row=Number(match[4])+(match[3]?0:dr);
    if(col<1||row<1||col>MAX_C||row>1048576)out+='#REF!';
    else out+=(match[1]?'$':'')+colName(col)+(match[3]?'$':'')+row;
    i+=match[0].length;
    continue;
   }
  }
  out+=source[i++];
 }
 return out;
}

function applyStyle(style){const b=bound(),sh=sheet();pushUndo();for(let r=b.r1;r<=b.r2;r++)for(let c=b.c1;c<=b.c2;c++){const a=address(r,c),o=cell(sh,a,true);o.s={...(o.s||{}),...style};}scheduleSave();renderGrid();}
function autoSum(){const b=bound(),sh=sheet();let target={r:selection.r1,c:selection.c1},top=target.r-1,bottom=target.r+1;if(b.r1!==b.r2||b.c1!==b.c2){target={r:Math.min(MAX_R,b.r2+1),c:b.c2};top=b.r2;bottom=target.r;}else{let start=target.r;while(start>1&&raw(sh,address(start-1,target.c))!=='')start--;if(start<target.r){const formula=`=SUM(${address(start,target.c)}:${address(target.r-1,target.c)})`;commitCell(address(target.r,target.c),formula);return;}let end=target.r;while(end<MAX_R&&raw(sh,address(end+1,target.c))!=='')end++;if(end>target.r){const formula=`=SUM(${address(target.r+1,target.c)}:${address(end,target.c)})`;commitCell(address(target.r,target.c),formula);return;}if(raw(sh,address(target.r,target.c))!==''){target.r=Math.min(MAX_R,target.r+1);top=target.r-1;}else{toast('Select a numeric range or a blank cell next to a list of numbers.');return;}}if(top<1){toast('Select a range to total.');return;}commitCell(address(target.r,target.c),`=SUM(${address(b.r1,b.c1)}:${address(b.r2,b.c2)})`);selection={r1:target.r,c1:target.c,r2:target.r,c2:target.c};renderGrid();}
function renderLearn(){const done=lessonDone(),mods=[...new Set(lessons.map(l=>l.module))];return `${pageIntro('LEARNING CENTRE','Learn by doing.','Short, practical lessons that connect each concept to a real spreadsheet task.')}<div class="challenge-progress"><span class="stat-icon purple">📚</span><div style="flex:1"><strong>${Object.keys(done).length} of ${lessons.length} lessons complete</strong><p>Learn a concept, then open the editor to try it yourself.</p><div class="progress-track" style="margin-top:10px"><span style="width:${100*Object.keys(done).length/lessons.length}%"></span></div></div><button class="button button-primary" data-view="editor">Open editor</button></div>${mods.map(m=>`<div class="section-heading"><div><h2>Module ${m}: ${moduleTitle(m)}</h2><p>${lessons.filter(l=>l.module===m).length} lessons · ${m<3?'Beginner':m<5?'Core skills':'Intermediate skills'}</p></div></div><div class="content-grid">${lessons.filter(l=>l.module===m).map(l=>`<article class="lesson-card"><div class="lesson-top"><span class="module-pill">Module ${l.module}</span>${done[l.id]?'<span class="status-pill">✓ Completed</span>':'<span class="difficulty">'+l.level+'</span>'}</div><h3>${esc(l.title)}</h3><p>${esc(l.desc)}</p><div class="lesson-meta">⏱ ${l.mins} min · Learn + practise</div><div class="card-actions"><button class="button button-primary button-small" data-action="open-lesson" data-id="${l.id}">${done[l.id]?'Review lesson':'Start lesson'} →</button></div></article>`).join('')}</div>`).join('')}`;}
function moduleTitle(n){return({1:'Spreadsheet Fundamentals',2:'Entering and Formatting Data',3:'Formulas and Cell References',4:'Essential Functions',5:'Organising Data',6:'Charts and Visualisation',7:'Practical Analysis',8:'Working with Files'})[n]||'Spreadsheet Skills';}
function renderFormulas(){return `${pageIntro('QUICK REFERENCE','Formula Library','Search practical spreadsheet functions, read the syntax, and insert a formula into the selected cell.')}<div class="search-row"><input id="formulaSearch" class="search-input" placeholder="Search functions, e.g. average, text, lookup…"><select class="filter-select" id="formulaGroup"><option value="all">All categories</option>${[...new Set(formulas.map(f=>f.group))].map(g=>`<option>${esc(g)}</option>`).join('')}</select></div><div id="formulaResults" class="content-grid">${formulaCards(formulas)}</div>`;}
function formulaCards(items){return items.map(f=>`<article class="formula-card"><div class="formula-group">${esc(f.group)}</div><h3>${f.name}()</h3><p>${esc(f.desc)}</p><div class="formula-code">${esc(f.syntax)}</div><p><strong>Example:</strong> ${esc(f.result)}</p><div class="card-actions"><button class="button button-secondary button-small" data-action="insert-function" data-formula="${esc(f.example)}">Insert into selected cell</button><button class="button button-soft button-small" data-action="copy-text" data-text="${esc(f.example)}">Copy</button></div></article>`).join('');}
function renderPractice(){const solved=challengeDone();return `${pageIntro('PRACTICE LAB','Solve real spreadsheet problems.','Each challenge opens a prepared sheet. Write the formula yourself, then check the actual result.',`<button class="button button-primary" data-view="editor">Open editor</button>`)}<div class="challenge-progress"><span class="stat-icon pink">🧠</span><div style="flex:1"><strong>${Object.keys(solved).length} of ${challenges.length} challenges solved</strong><p>Practice is checked against the calculated value in the target cell.</p><div class="progress-track" style="margin-top:10px"><span style="width:${100*Object.keys(solved).length/challenges.length}%"></span></div></div><strong>${challenges.filter(c=>solved[c.id]).reduce((s,c)=>s+c.points,0)} XP</strong></div><div class="content-grid">${challenges.map(c=>`<article class="challenge-card"><div class="lesson-top"><span class="difficulty">${c.level}</span>${solved[c.id]?'<span class="status-pill">✓ Solved</span>':`<span class="module-pill">${c.points} XP</span>`}</div><h3>${esc(c.title)}</h3><p>${esc(c.desc)}</p><div class="lesson-meta">Target cell: <strong>${c.target}</strong></div><div class="card-actions"><button class="button button-primary button-small" data-action="start-challenge" data-id="${c.id}">${solved[c.id]?'Try again':'Start challenge'} →</button><button class="button button-secondary button-small" data-action="challenge-hint" data-id="${c.id}">Hint</button></div></article>`).join('')}</div>`;}
function renderProjects(){return `${pageIntro('PROJECT GALLERY','Start with something useful.','Open a ready-made spreadsheet, inspect its formulas, and adapt it to your own idea.')}<div class="content-grid">${projects.map(p=>`<article class="project-card" data-action="project-preview" data-id="${p.id}"><div class="project-top"><span class="project-emoji" style="background:var(--${p.color})">${p.emoji}</span><span class="difficulty">${p.level}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.desc)}</p><div class="lesson-meta">Skills: ${esc(p.skills)}</div><div class="card-actions"><button class="button button-primary button-small" data-action="load-project" data-id="${p.id}">Open project →</button><button class="button button-secondary button-small" data-action="project-preview" data-id="${p.id}">Preview</button></div></article>`).join('')}</div>`;}
function renderWorkbooks(){const books=savedBooks();return `${pageIntro('YOUR FILES','My Workbooks','Open a saved workbook, duplicate it, or export a copy for safekeeping.',`<button class="button button-primary" data-action="new-workbook">＋ New workbook</button>`)}${books.length?`<div class="content-grid">${books.map(b=>`<article class="workbook-card"><div class="workbook-top"><span class="project-emoji" style="background:var(--green)">📗</span><span class="status-pill">Saved</span></div><h3>${esc(b.name)}</h3><p>${(b.workbook?.sheets||[]).length} worksheet(s) · Last saved ${new Date(b.updatedAt||Date.now()).toLocaleString()}</p><div class="card-actions"><button class="button button-primary button-small" data-action="open-book" data-id="${esc(b.id)}">Open</button><button class="button button-secondary button-small" data-action="duplicate-book" data-id="${esc(b.id)}">Duplicate</button><button class="button button-danger button-small" data-action="delete-book" data-id="${esc(b.id)}">Delete</button></div></article>`).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">📂</div><h3>No saved workbooks yet</h3><p>Save a workbook from the editor to keep it in this list.</p><button class="button button-primary" data-view="editor">Open editor</button></div>`}`;}

