function modal(title,desc,body,buttons='',wide=false){$('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="modal-backdrop"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><header class="modal-header"><div><h2>${esc(title)}</h2><p>${esc(desc||'')}</p></div><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><div class="modal-body">${body}</div>${buttons?`<footer class="modal-footer">${buttons}</footer>`:''}</div></div>`;}
function closeModal(){$('#modalRoot').innerHTML='';}
function openLesson(id){const l=lessons.find(x=>x.id===id);if(!l)return;const done=lessonDone();modal(`Module ${l.module} · ${l.title}`,l.desc,`<div class="lesson-content"><p class="modal-text">${esc(l.body)}</p><div class="formula-code">${esc(l.example)}</div><div class="lesson-task"><strong>Try it</strong><p>${esc(l.task)}</p></div><p class="modal-text" style="margin-top:15px">You can open the editor now and experiment with the concept using your own cells.</p></div>`,`${done[id]?'':'<button class="button button-secondary" data-action="mark-lesson" data-id="'+id+'">Mark complete</button>'}<button class="button button-primary" data-action="lesson-try" data-id="${id}">Open editor →</button>`,false);}
function loadProject(id){const p=projects.find(x=>x.id===id);if(!p)return;wb=createBook(p.title);setRows(sheet(),p.rows);sheet().cells={...sheet().cells};wb.name=p.title;selection={r1:1,c1:1,r2:1,c2:1};cache.clear();saveCurrent();closeModal();setView('editor');toast(`${p.title} loaded. Change any cell to make it yours.`);}
function previewProject(id){const p=projects.find(x=>x.id===id);if(!p)return;const preview=p.rows.slice(0,7).map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('');modal(p.title,p.desc,`<p class="modal-text">${esc(p.skills)}. This template opens as an editable workbook with formulas preserved.</p><div class="table-preview"><table><tbody>${preview}</tbody></table></div><p class="modal-text" style="margin-top:12px">Sample: ${p.rows.length-1} data rows (including summary rows where shown). You can add rows, format cells, or create charts.</p>`,`<button class="button button-primary" data-action="load-project" data-id="${id}">Open in editor →</button>`,true);}
function startChallenge(id){const ch=challenges.find(x=>x.id===id);if(!ch)return;ribbon='Data';wb=createBook('Practice · '+ch.title);setRows(sheet(),ch.rows);wb.practiceId=id;selection={r1:1,c1:1,r2:1,c2:1};practiceId=id;saveCurrent();setView('editor');toast(`Challenge loaded. Complete ${ch.target}, then use Check challenge in the Data toolbar.`);}
function checkChallenge(id){const ch=challenges.find(x=>x.id===id||x.id===practiceId||x.id===wb.practiceId);if(!ch){toast('Start a challenge from Practice Lab first.');return;}const v=computed(sheet(),ch.target),ok=typeof ch.expected==='number'?typeof v==='number'&&Math.abs(v-ch.expected)<1e-7:String(v).trim().toLowerCase()===String(ch.expected).trim().toLowerCase();if(ok){const d=challengeDone();d[ch.id]=true;storeSet(STORE.practice,JSON.stringify(d));toast(`Correct! ${ch.points} XP earned.`);render();}else toast(`Not quite. Check the formula and result in ${ch.target}.`);}

function openSavedWorkbooks(){
 const books=savedBooks();
 if(!books.length){toast('No saved workbooks yet. Use Save to keep this workbook.');return;}
 const body=`<div class="saved-workbook-list">${books.map(b=>`<button class="saved-workbook-option" data-action="open-book" data-id="${esc(b.id)}"><span class="saved-workbook-icon">▦</span><span><strong>${esc(b.name)}</strong><small>${new Date(b.updatedAt||Date.now()).toLocaleString()}</small></span><span class="saved-workbook-open">Open →</span></button>`).join('')}</div>`;
 modal('Open saved workbook','Choose a workbook saved in this browser.',body,`<button class="button button-secondary" data-action="close-modal">Close</button>`);
}

function openFormulaPicker(){modal('Insert a function','Choose a function and insert its example into the selected cell.',`<div class="form-field"><label for="functionSelect">FUNCTION</label><select id="functionSelect">${formulas.map(f=>`<option value="${esc(f.example)}">${f.name} — ${esc(f.desc)}</option>`).join('')}</select></div><div id="functionDetails" class="modal-text">Choose a function to preview its syntax.</div>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="apply-function">Insert formula</button>`);$('#functionSelect')?.addEventListener('change',showFunctionDetails);showFunctionDetails();}
function showFunctionDetails(){const v=$('#functionSelect')?.value;const f=formulas.find(x=>x.example===v);const d=$('#functionDetails');if(d&&f)d.innerHTML=`<div class="formula-code">${esc(f.example)}</div>${esc(f.desc)}<br><br>${esc(f.result)}`;}
function shiftGrid(axis,at,delta){const sh=sheet(),isRow=axis==='row',max=isRow?MAX_R:MAX_C;if(delta<0&&at===1&&isRow){toast('Keep the first row for headings; delete data rows below it.');return;}if(delta<0&&at===1&&!isRow){toast('Select a different column to delete.');return;}if(delta>0&&((isRow&&getUsed(sh).r>=MAX_R)||(!isRow&&getUsed(sh).c>=MAX_C))){toast('The worksheet has reached its current grid limit.');return;}pushUndo();const next={};for(const [oldA,o0] of Object.entries(sh.cells)){const p=parseAddress(oldA);if(!p)continue;let idx=isRow?p.r:p.c;if(delta>0&&idx>=at)idx++;else if(delta<0){if(idx===at)continue;if(idx>at)idx--;}if(idx<1||idx>max)continue;const q={r:isRow?idx:p.r,c:isRow?p.c:idx},a=address(q.r,q.c),o=clone(o0);if(String(o.v||'').startsWith('='))o.v=adjustFormulaRefs(o.v,axis,at,delta);next[a]=o;}sh.cells=next;selection={r1:Math.min(MAX_R,at+(delta<0?0:0)),c1:selection.c1,r2:Math.min(MAX_R,at+(delta<0?0:0)),c2:selection.c1};if(!isRow)selection={r1:selection.r1,c1:Math.max(1,at),r2:selection.r1,c2:Math.max(1,at)};cache.clear();renderGrid();scheduleSave();toast(`${delta>0?'Inserted':'Deleted'} ${isRow?'row':'column'} ${at}.`);}
function adjustFormulaRefs(formula,axis,at,delta){return String(formula).replace(/"(?:""|[^\"])*"|(\$?)([A-Z]{1,3})(\$?)(\d+)/gi,(m,ac,col,ar,row)=>{if(m.startsWith('"'))return m;let r=Number(row),c=colNum(col);if(axis==='row'){if(delta>0&&r>=at)r++;else if(delta<0&&r===at)return '#REF!';else if(delta<0&&r>at)r--;}else{if(delta>0&&c>=at)c++;else if(delta<0&&c===at)return '#REF!';else if(delta<0&&c>at)c--;}if(r<1||c<1)return '#REF!';return `${ac?'$':''}${colName(c)}${ar?'$':''}${r}`;});}
function openChartDialog(){const b=bound();modal('Create a chart','Choose a data range. Use labels in the first column and numbers in the next column (for example A1:B5). A single numeric column also works; blank cells are ignored.',`<div class="form-field"><label>CHART TITLE</label><input id="chartTitle" value="${esc(wb.name+' chart')}"></div><div class="form-field"><label>CHART TYPE</label><select id="chartType"><option value="column">Column chart</option><option value="bar">Bar chart</option><option value="line">Line chart</option><option value="pie">Pie chart</option><option value="area">Area chart</option><option value="scatter">Scatter chart</option></select></div><div class="form-field"><label>DATA RANGE</label><input id="chartRange" value="${rangeLabel(b)}" placeholder="A1:B5"></div><p class="modal-text">The chart uses the first column for category labels and the second column for values. If you select only one numeric column, row addresses are used as labels. Make sure the range points to your actual data.</p>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="create-chart">Create chart</button>`);}
function rangeFromText(txt){const m=String(txt||'').trim().toUpperCase().split(':');const a=parseAddress(m[0]);const b=parseAddress(m[1]||m[0]);return a&&b?{r1:Math.min(a.r,b.r),c1:Math.min(a.c,b.c),r2:Math.max(a.r,b.r),c2:Math.max(a.c,b.c)}:null;}
function chartItemsForRange(sh,r){const items=[],singleColumn=r.c1===r.c2;for(let row=r.r1+(singleColumn?0:1);row<=r.r2;row++){const rawValue=singleColumn?computed(sh,address(row,r.c1)):computed(sh,address(row,r.c1+1));if(rawValue===''||rawValue===null||rawValue===undefined)continue;const value=num(rawValue);if(!Number.isFinite(value))continue;let label=singleColumn?address(row,r.c1):String(computed(sh,address(row,r.c1))??'').trim();if(!label)label=singleColumn?address(row,r.c1):`Row ${row}`;items.push({label:String(label),value});}return items;}
function makeChart(){const title=$('#chartTitle')?.value.trim()||'My chart',type=$('#chartType')?.value||'column',range=rangeFromText($('#chartRange')?.value);if(!range||range.r2<range.r1){toast('Enter a valid data range, for example A1:B5.');return;}const items=chartItemsForRange(sheet(),range);if(!items.length){toast('No numeric chart values found. Check the selected range and put numbers in its value column.');return;}if(type==='pie'&&!items.some(x=>x.value>0)){toast('A pie chart needs at least one value greater than zero.');return;}const sh=sheet();sh.charts=sh.charts||[];sh.charts.push({id:`ch${Date.now()}`,title,type,range});closeModal();renderGrid();scheduleSave();toast('Chart added. Change the source cells to update it.');}
function renderChartSlot(){const slot=$('#chartSlot');if(!slot)return;const charts=sheet().charts||[];slot.innerHTML=charts.map(ch=>`<section class="chart-panel"><div class="chart-panel-head"><div><strong>${esc(ch.title)}</strong><span style="margin-left:10px">${esc(ch.type)} chart · ${rangeLabel(ch.range)}</span></div><div><button class="button button-secondary button-small" data-action="edit-chart" data-id="${ch.id}">Edit</button> <button class="button button-secondary button-small" data-action="remove-chart" data-id="${ch.id}">Remove</button></div></div><div class="chart-stage">${chartSvg(ch)}</div></section>`).join('');}
function chartSvg(ch){const sh=sheet(),r=ch.range,items=chartItemsForRange(sh,r);if(!items.length)return '<div class="chart-empty">No numeric data found in this range. Select Edit and choose the cells that contain your data.</div>';if(ch.type==='pie'&&!items.some(x=>x.value>0))return '<div class="chart-empty">Pie charts need positive values. Check the chart data range.</div>';const w=740,h=230,pad=35,max=Math.max(1,...items.map(x=>Math.abs(x.value))),min=Math.min(0,...items.map(x=>x.value)),range=max-min||1;const x=i=>pad+(i+.5)*(w-pad*2)/items.length,y=v=>h-pad-(v-min)/range*(h-pad*2);let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(ch.title)}"><line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}" stroke="#dfe2ee"/><line x1="${pad}" y1="${pad}" x2="${pad}" y2="${h-pad}" stroke="#dfe2ee"/>`;const colors=['#6558F5','#69A7F4','#F28CB3','#6BCB9A','#F1C65A','#A78BFA','#F59A61'];
if(ch.type==='pie'){const total=items.reduce((s,x)=>s+Math.max(0,x.value),0)||1;let angle=-Math.PI/2;items.forEach((it,i)=>{const a2=angle+Math.max(0,it.value)/total*Math.PI*2,x1=200+90*Math.cos(angle),y1=110+90*Math.sin(angle),x2=200+90*Math.cos(a2),y2=110+90*Math.sin(a2),large=a2-angle>Math.PI?1:0;svg+=`<path d="M 200 110 L ${x1} ${y1} A 90 90 0 ${large} 1 ${x2} ${y2} Z" fill="${colors[i%colors.length]}" stroke="white" stroke-width="2"/>`;angle=a2;});svg+=items.map((it,i)=>`<rect x="370" y="${30+i*27}" width="10" height="10" rx="3" fill="${colors[i%colors.length]}"/><text x="388" y="${39+i*27}" font-size="11" fill="#545975">${esc(it.label.slice(0,24))}: ${trim(it.value,2)}</text>`).join('');}
else if(ch.type==='scatter'){const xs=items.map((it,i)=>Number.isFinite(num(it.label))?num(it.label):i+1),xmin=Math.min(...xs),xmax=Math.max(...xs),xd=xmax-xmin||1;items.forEach((it,i)=>{const xx=pad+(xs[i]-xmin)/xd*(w-pad*2),yy=h-pad-(it.value-min)/range*(h-pad*2);svg+=`<circle cx="${xx}" cy="${yy}" r="5" fill="#6558F5" opacity=".88"/><text x="${xx}" y="${h-8}" font-size="10" text-anchor="middle" fill="#777b96">${esc(it.label.slice(0,9))}</text>`;});svg+=`<text x="${w/2}" y="15" font-size="10" text-anchor="middle" fill="#777b96">X values from ${esc(address(r.r1+1,r.c1))}:${esc(address(r.r2,r.c1))}</text>`;}
else if(ch.type==='line'||ch.type==='area'){const pts=items.map((it,i)=>`${x(i)},${y(it.value)}`).join(' ');if(ch.type==='area')svg+=`<polygon points="${x(0)},${h-pad} ${pts} ${x(items.length-1)},${h-pad}" fill="#6558F5" opacity=".15"/>`;svg+=`<polyline points="${pts}" fill="none" stroke="#6558F5" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>`;items.forEach((it,i)=>{svg+=`<circle cx="${x(i)}" cy="${y(it.value)}" r="4" fill="#6558F5"/><text x="${x(i)}" y="${h-8}" font-size="10" text-anchor="middle" fill="#777b96">${esc(it.label.slice(0,11))}</text>`;});}
else if(ch.type==='bar'){const rowH=(h-pad*2)/items.length,bw= w-pad*2;items.forEach((it,i)=>{const yy=pad+i*rowH+rowH*.2,width=Math.max(1,(it.value-min)/range*bw);svg+=`<text x="${pad-7}" y="${yy+rowH*.42}" font-size="10" text-anchor="end" fill="#777b96">${esc(it.label.slice(0,14))}</text><rect x="${pad}" y="${yy}" width="${width}" height="${Math.max(8,rowH*.58)}" rx="4" fill="${colors[i%colors.length]}"/><text x="${Math.min(w-24,pad+width+5)}" y="${yy+rowH*.42}" font-size="10" fill="#555a73">${trim(it.value,2)}</text>`;});}
else{const bw=Math.min(48,(w-pad*2)/items.length*.62);items.forEach((it,i)=>{let yy=y(it.value),base=y(0),height=Math.max(1,Math.abs(base-yy)),xx=x(i)-bw/2;svg+=`<rect x="${xx}" y="${Math.min(yy,base)}" width="${bw}" height="${height}" rx="4" fill="${colors[i%colors.length]}"/><text x="${x(i)}" y="${Math.min(yy,base)-5}" font-size="10" text-anchor="middle" fill="#555a73">${trim(it.value,2)}</text><text x="${x(i)}" y="${h-8}" font-size="10" text-anchor="middle" fill="#777b96">${esc(it.label.slice(0,11))}</text>`;});}return svg+'</svg>';}

function openDataValidation(initial='list'){modal('Data validation','Limit the selected cells to a dropdown list or a numeric range.',`<div class="form-field"><label>VALIDATION TYPE</label><select id="validationType"><option value="list" ${initial==='list'?'selected':''}>Dropdown list</option><option value="number" ${initial==='number'?'selected':''}>Whole/decimal number range</option></select></div><div class="form-field" id="validationListField"><label>ALLOWED VALUES (comma-separated)</label><input id="validationList" value="Planned, Doing, Done"></div><div class="form-field" id="validationNumberField" style="display:none"><label>MINIMUM</label><input type="number" id="validationMin" value="0"><label>MAXIMUM</label><input type="number" id="validationMax" value="100"></div><p class="modal-text">Selected range: ${rangeLabel()}</p>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="apply-validation">Apply validation</button>`);$('#validationType').addEventListener('change',()=>{const list=$('#validationType').value==='list';$('#validationListField').style.display=list?'grid':'none';$('#validationNumberField').style.display=list?'none':'grid';});}
function applyValidation(){const b=bound(),sh=sheet(),type=$('#validationType').value;pushUndo();for(let r=b.r1;r<=b.r2;r++)for(let c=b.c1;c<=b.c2;c++){const a=address(r,c);if(type==='list')sh.validation[a]={type,values:$('#validationList').value.split(',').map(x=>x.trim()).filter(Boolean)};else sh.validation[a]={type:'number',min:Number($('#validationMin').value),max:Number($('#validationMax').value)};}closeModal();renderGrid();scheduleSave();toast('Validation applied to the selected cells.');}
function openConditional(){modal('Conditional formatting','Highlight cells whose values match a simple rule.',`<div class="form-field"><label>RULE</label><select id="cfOp"><option value="gt">Greater than</option><option value="lt">Less than</option><option value="eq">Equal to</option><option value="blank">Is blank</option></select></div><div class="form-field"><label>VALUE</label><input id="cfValue" type="text" value="80"></div><div class="form-field"><label>HIGHLIGHT COLOUR</label><input id="cfColor" type="color" value="#D9F8E7"></div><p class="modal-text">Applies to ${rangeLabel()}.</p>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="apply-conditional">Apply rule</button>`);}
function applyConditional(){const b=bound(),sh=sheet(),rule={id:`cf${Date.now()}`,range:b,op:$('#cfOp').value,value:$('#cfValue').value,color:$('#cfColor').value};sh.conditionalRules=sh.conditionalRules||[];sh.conditionalRules.push(rule);closeModal();renderGrid();scheduleSave();toast('Conditional formatting applied.');}
function openFindReplace(){modal('Find and replace','Search displayed cell contents and optionally replace matching text.',`<div class="form-field"><label>FIND</label><input id="findValue" placeholder="Text or number"></div><div class="form-field"><label>REPLACE WITH</label><input id="replaceValue" placeholder="Replacement (leave empty to clear)"></div><label style="display:flex;gap:8px;align-items:center;font-size:11px"><input type="checkbox" id="replaceAll" checked> Replace all matches in this worksheet</label>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="do-find-replace">Replace</button>`);}
function doFindReplace(){const needle=$('#findValue').value;if(!needle){toast('Enter text to find.');return;}const replacement=$('#replaceValue').value,sh=sheet();pushUndo();let n=0;for(const [a,o] of Object.entries(sh.cells)){if(String(o.v??'').includes(needle)){setCell(sh,a,$('#replaceAll').checked?String(o.v).split(needle).join(replacement):String(o.v).replace(needle,replacement));n++;if(!$('#replaceAll').checked)break;}}closeModal();renderGrid();scheduleSave();toast(`${n} cell(s) updated.`);}
