/* =========================================
   WORKBOOK ACTIONS + EVENT HANDLERS
========================================= */
function newWorkbook(){
 modal('New workbook','Create a blank spreadsheet workbook.',`<div class="form-field"><label>WORKBOOK NAME</label><input id="newBookName" value="My Spreadsheet" maxlength="80" autofocus></div>`,
 `<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="create-workbook">Create workbook</button>`);
 $('#newBookName')?.focus();
 $('#newBookName')?.select();
}

function createNewWorkbook(){
 const name=$('#newBookName')?.value?.trim()||'My Spreadsheet';
 wb=createBook(name);
 selection={r1:1,c1:1,r2:1,c2:1};
 undoStack=[];redoStack=[];practiceId=null;cache.clear();
 saveCurrent();closeModal();setView('editor');
 toast('Blank workbook created.');
}

function loadBook(id){const b=savedBooks().find(x=>x.id===id);if(!b){toast('Saved workbook not found.');return;}wb=clone(b.workbook);wb.id=b.id;selection={r1:1,c1:1,r2:1,c2:1};cache.clear();saveCurrent();setView('editor');toast(`${wb.name} opened.`);}
function duplicateBook(id){const b=savedBooks().find(x=>x.id===id);if(!b)return;const copy=clone(b.workbook);copy.id=`wb_${Date.now().toString(36)}`;copy.name=`${b.name} copy`;copy.updatedAt=Date.now();const a=savedBooks();a.unshift({id:copy.id,name:copy.name,updatedAt:copy.updatedAt,workbook:copy});storeSet(STORE.books,JSON.stringify(a.slice(0,35)));render();toast('Workbook duplicated.');}
function deleteBook(id){const a=savedBooks().filter(x=>x.id!==id);storeSet(STORE.books,JSON.stringify(a));render();toast('Saved workbook deleted.');}
function worksheetMenu(){modal('Worksheet options',`Current worksheet: ${sheet().name}`,`<div class="form-field"><label>RENAME WORKSHEET</label><input id="renameSheetInput" value="${esc(sheet().name)}" maxlength="31"></div><div class="form-field"><label>DUPLICATE WORKSHEET</label><p class="modal-text">Make a copy of the current sheet, including cell values and formulas.</p></div><p class="modal-text">${wb.sheets.length>1?'You can also delete this sheet.':'A workbook must keep at least one worksheet.'}</p>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-danger" data-action="delete-sheet" ${wb.sheets.length<=1?'disabled':''}>Delete sheet</button><button class="button button-secondary" data-action="duplicate-sheet">Duplicate</button><button class="button button-primary" data-action="rename-sheet">Rename</button>`);}
function addSheet(){const n=wb.sheets.length+1;wb.sheets.push(mkSheet(`Sheet${n}`));wb.activeSheet=wb.sheets.length-1;selection={r1:1,c1:1,r2:1,c2:1};saveCurrent();renderGrid();toast('Worksheet added.');}
function duplicateSheet(){const src=sheet(),cp=clone(src);cp.id=`s${Date.now().toString(36)}`;cp.name=(src.name+' copy').slice(0,31);wb.sheets.push(cp);wb.activeSheet=wb.sheets.length-1;selection={r1:1,c1:1,r2:1,c2:1};closeModal();saveCurrent();renderGrid();toast('Worksheet duplicated.');}
function renameSheet(){const v=$('#renameSheetInput').value.trim().slice(0,31);if(!v){toast('Enter a worksheet name.');return;}sheet().name=v;closeModal();saveCurrent();renderGrid();}
function deleteSheet(){if(wb.sheets.length<=1)return;const name=sheet().name;wb.sheets.splice(wb.activeSheet,1);wb.activeSheet=Math.max(0,wb.activeSheet-1);selection={r1:1,c1:1,r2:1,c2:1};closeModal();saveCurrent();renderGrid();toast(`${name} deleted.`);}
