function toggleFilter(){const sh=sheet();if(sh.filter?.active){sh.filter.active=false;renderGrid();toast('Filter cleared.');return;}modal('Filter worksheet','Show only rows where the selected column contains this text.',`<div class="form-field"><label>FILTER COLUMN</label><input id="filterColumn" value="${colName(selection.c1)}" maxlength="3"></div><div class="form-field"><label>CONTAINS</label><input id="filterQuery" placeholder="e.g. Food, Pass, Aarav"></div><p class="modal-text">Row 1 is treated as the header and will remain visible.</p>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="apply-filter">Apply filter</button>`);}
function applyFilter(){const col=colNum($('#filterColumn').value.toUpperCase());if(!Number.isInteger(col)||col<1||col>MAX_C){toast('Enter a valid column such as A or C.');return;}sheet().filter={active:true,col,query:$('#filterQuery').value};closeModal();renderGrid();toast('Filter applied. Use Data → Filter again to clear it.');}
